```c
// C program for the function called parse_names_from_string
// Contains target function implementation and dependency signatures

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
int parse_names_from_string(const char *input, char names[][MAX_NAME_LEN], int max_names)
{
    if (input == NULL || names == NULL || max_names <= 0)
        return -1;

    int count = 0;
    const char *ptr = input;

    while (*ptr != '\0' && count < max_names)
    {
        /* Skip whitespace and commas */
        while (*ptr == ' ' || *ptr == ',' || *ptr == '\n' || *ptr == '\r')
            ptr++;

        if (*ptr == '\0')
            break;

        /* Expect opening quote */
        if (*ptr != '"')
        {
            ptr++;
            continue;
        }
        ptr++; /* skip opening quote */

        /* Copy name until closing quote */
        int i = 0;
        while (*ptr != '\0' && *ptr != '"' && i < MAX_NAME_LEN - 1)
        {
            names[count][i++] = *ptr++;
        }
        names[count][i] = '\0';

        if (*ptr == '"')
            ptr++; /* skip closing quote */

        if (i > 0) /* only count non-empty names */
            count++;
    }

    return count;
}

